"""UI cho P3 (Prompt Hub/canvas/so sánh model) và P4 (Builder, Duyệt HITL, Studio, Mô phỏng)."""
from ui import page

HUB = page("hub", "Prompt Hub", """<main>
<div class="grid2" style="grid-template-columns:300px 1fr">
<div class="card"><h3>Prompt</h3><div id="pl"></div><hr><button class="s" onclick="newP()">+ prompt mới</button>
<h3 style="margin-top:14px">Webhook khi commit</h3><small>Nội bộ: tự gửi; bên ngoài: chỉ tạo bản nháp Outbox.</small><div class="row"><input id="whu" placeholder="https://..." style="flex:1"><button class="s" onclick="addWh()">Thêm</button></div><div id="whl"></div></div>
<div style="display:grid;gap:14px">
<div class="card"><h2 id="pt">Soạn prompt</h2>
<div class="row"><input id="pn" placeholder="tên prompt (vd tom_tat)"><select id="pm"></select><input id="ptemp" type="number" step="0.1" min="0" max="2" value="0.3" style="width:70px"><input id="pmsg" placeholder="commit message" style="flex:1"><input id="ptag" placeholder="tag (vd prod)" style="width:110px"><button onclick="commit()">Commit</button></div>
<label>Template (biến dạng {{ten}})</label><textarea id="ptpl" rows="9"></textarea>
<div class="grid2"><div><label>Biến (JSON)</label><textarea id="pvars" rows="3">{}</textarea></div><div><label>Output schema (JSON, tuỳ chọn) — structured output</label><textarea id="psch" rows="3"></textarea></div></div>
<div class="row" style="margin-top:8px"><b>Canvas AI:</b><input id="imp" style="flex:1" value="Làm prompt rõ ràng, có cấu trúc, nêu rõ định dạng đầu ra, thêm ràng buộc an toàn."><button class="g" onclick="improve()"><svg class="ic"><use href="#i-sparkles"/></svg> Cải thiện bằng AI</button></div>
<div id="impres"></div></div>
<div class="card"><h3>So sánh nhiều model (song song, không fallback)</h3><div class="row" id="mms"></div><button onclick="multi()" style="margin-top:6px">Chạy so sánh</button>
<div id="mres" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px;margin-top:10px"></div></div>
<div class="card"><h3>Chạy trên dataset (tạo experiment)</h3><div class="row"><select id="bds"></select><select id="bev" multiple size="3"></select><button onclick="batch()">Chạy phiên bản đang chọn</button><span id="bres"></span></div></div>
<div class="card" id="vcard" style="display:none"><h3>Lịch sử commit · tag · diff</h3><div id="used"></div><table id="vl"></table><div class="row"><select id="da"></select>→<select id="db"></select><button class="s" onclick="diff()">Diff</button></div><pre id="dout"></pre></div>
</div></div></main>""", r"""
let CUR=null,VERS=[];
async function load(){const ps=await api('api/hub');$('pl').innerHTML=ps.map(p=>`<div style="padding:6px;border-bottom:1px solid #eee;cursor:pointer" onclick="openP(${p.id})"><b>${esc(p.name)}</b> <small>v${p.latest} · ${p.commits} commit</small><br>${(p.tags||[]).map(t=>`<span class="tag ro">${esc(t.tag)}→v${t.version}</span>`).join('')}</div>`).join('')||'<small>Chưa có prompt</small>';
 const w=await api('api/hub/webhooks/list');$('whl').innerHTML=w.map(x=>`<div><small>${esc(x.url)}</small> <button class="s" onclick="api('api/hub/webhooks/${x.id}','DELETE').then(load)">x</button></div>`).join('')}
function newP(){CUR=null;$('pt').textContent='Soạn prompt mới';['pn','ptpl','pmsg','ptag','psch'].forEach(i=>$(i).value='');$('pvars').value='{}';$('vcard').style.display='none'}
function fill(v){$('ptpl').value=v.template;$('pm').value=v.model||$('pm').value;$('ptemp').value=v.temperature??0.3;$('pvars').value=JSON.stringify(v.variables||{});$('psch').value=v.output_schema?JSON.stringify(v.output_schema):''}
async function openP(id){const d=await api('api/hub/'+id);CUR=d;VERS=d.versions;$('pn').value=d.prompt.name;$('pt').textContent='Prompt: '+d.prompt.name;fill(d.versions[0]);$('vcard').style.display='block';
 const tg={};d.tags.forEach(t=>(tg[t.version]=tg[t.version]||[]).push(t.tag));
 $('vl').innerHTML='<tr><th>v</th><th>Lúc</th><th>Commit message</th><th>Model</th><th>Tag</th><th></th></tr>'+d.versions.map(v=>`<tr><td>v${v.version}${v.parent_version?` <small>←v${v.parent_version}</small>`:''}</td><td>${vn(v.created)}</td><td>${esc(v.note||'')}</td><td>${esc(v.model)} · ${v.temperature}</td><td>${(tg[v.version]||[]).map(t=>`<span class="tag ro">${esc(t)} <a style="cursor:pointer" onclick="untag('${t}')">×</a></span>`).join('')}</td>
 <td><button class="s" onclick="fill(VERS.find(x=>x.version==${v.version}))">Mở</button> <button class="s" onclick="tag(${v.version})">Gắn tag</button></td></tr>`).join('');
 const o=d.versions.map(v=>`<option value="${v.version}">v${v.version}</option>`).join('');$('da').innerHTML=o;$('db').innerHTML=o;if(d.versions[1])$('da').value=d.versions[1].version;
 $('used').innerHTML=d.used_by.length?'<p>Agent đang dùng: '+d.used_by.map(a=>`<span class="tag">#${a.id} ${esc(a.name)} (${esc(a.ref)})</span>`).join('')+'</p>':'<p><small>Chưa agent nào dùng. Gắn bằng trường <code>prompt_ref</code> (vd <code>'+esc(d.prompt.name)+':prod</code>) ở trang Agents.</small></p>'}
function J(id){const t=$(id).value.trim();return t?JSON.parse(t):null}
async function commit(){try{const r=await api('api/hub/commit','POST',{name:$('pn').value,template:$('ptpl').value,model:$('pm').value,temperature:+$('ptemp').value,variables:J('pvars')||{},output_schema:J('psch'),message:$('pmsg').value||null,tag:$('ptag').value||null,parent_version:CUR?CUR.versions[0].version:null});flash('Đã commit v'+r.version);await load();openP(r.id)}catch(e){flash(e.message,1)}}
async function tag(v){const t=prompt('Tên tag (vd prod, staging):');if(!t)return;await api(`api/hub/${CUR.prompt.id}/tags`,'POST',{tag:t,version:v});openP(CUR.prompt.id);load()}
async function untag(t){await api(`api/hub/${CUR.prompt.id}/tags/${t}`,'DELETE');openP(CUR.prompt.id);load()}
async function diff(){const d=await api(`api/hub/${CUR.prompt.id}/diff?a=${$('da').value}&b=${$('db').value}`);$('dout').innerHTML=esc(d.diff||'(giống nhau)').split('\n').map(l=>l.startsWith('+')?`<span style="color:#15803d">${l}</span>`:l.startsWith('-')?`<span style="color:#b91c1c">${l}</span>`:l).join('\n')+'\n\n'+esc(JSON.stringify(d.settings))}
let IMP=null;
async function improve(){$('impres').innerHTML='<p>Đang nhờ AI viết lại…</p>';try{const r=await api('api/prompts/improve','POST',{template:$('ptpl').value,instructions:$('imp').value});IMP=r;
 $('impres').innerHTML=`<h4>Đề xuất (${esc(r.model)})</h4><ul>${r.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${r.missing_variables.length?`<p class="err">Thiếu biến: ${esc(r.missing_variables.join(', '))}</p>`:''}<pre>${esc(r.diff).split('\n').map(l=>l.startsWith('+')?`<span style="color:#15803d">${l}</span>`:l.startsWith('-')?`<span style="color:#b91c1c">${l}</span>`:l).join('\n')}</pre><button onclick="$('ptpl').value=IMP.improved;$('pmsg').value='Cải thiện bằng AI';flash('Đã áp dụng vào editor — bấm Commit để lưu')">Áp dụng</button> <button class="g" onclick="$('impres').innerHTML=''">Bỏ</button>`}catch(e){$('impres').innerHTML='<p class="err">'+esc(e.message)+'</p>'}}
async function multi(){const ms=[...document.querySelectorAll('.mm:checked')].map(x=>x.value);if(!ms.length)return flash('Chọn model',1);$('mres').innerHTML='<p>Đang chạy…</p>';
 try{const r=await api('api/playground/multi','POST',{template:$('ptpl').value,variables:J('pvars')||{},models:ms,temperature:+$('ptemp').value,output_schema:J('psch'),prompt_ref:CUR?CUR.prompt.name:null});
 $('mres').innerHTML=r.results.map(x=>`<div class="card" style="padding:10px"><b>${esc(x.model)}</b> <small>${x.ms} ms · ${x.input_tokens}→${x.output_tokens} tok · ${usd(x.cost_usd)}${x.schema_valid!=null?(x.schema_valid?' · <span class="ok">schema ✓</span>':' · <span class="err">schema ✗</span>'):''}</small>${x.error?`<pre class="err">${esc(x.error)}</pre>`:`<pre>${esc(x.output)}</pre>`}</div>`).join('')}catch(e){$('mres').innerHTML='<p class="err">'+esc(e.message)+'</p>'}}
async function batch(){if(!CUR)return flash('Mở một prompt đã commit trước',1);const v=VERS.find(x=>x.template===$('ptpl').value);try{const r=await api('api/playground/batch','POST',{prompt_id:CUR.prompt.id,version:v?v.version:null,dataset_id:+$('bds').value,evaluator_ids:[...$('bev').selectedOptions].map(o=>+o.value)});$('bres').innerHTML=`<a href="experiments">Experiment #${r.experiment_id} đang chạy →</a>`}catch(e){flash(e.message,1)}}
async function addWh(){try{await api('api/hub/webhooks','POST',{url:$('whu').value});$('whu').value='';load()}catch(e){flash(e.message,1)}}
(async()=>{const m=await api('api/models');const ids=(m.models||m).map(x=>x.id||x.name||x);$('pm').innerHTML=ids.map(x=>`<option>${esc(x)}</option>`).join('');
 const pref=['gemini-3.1-flash-lite','gemini-flash-lite-latest','gemini-3-flash-preview','gemini-3.6-flash','gemini-3.5-flash-lite','gemini-3.8-flash'];const sh=[...pref.filter(x=>ids.includes(x)),...ids.filter(x=>!pref.includes(x))].slice(0,10);
 $('mms').innerHTML=sh.map(x=>`<label style="margin:0"><input type="checkbox" class="mm" value="${esc(x)}" ${['gemini-3.1-flash-lite','gemini-flash-lite-latest'].includes(x)?'checked':''}> ${esc(x)}</label>`).join(' ');
 const ds=await api('api/datasets');$('bds').innerHTML=ds.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('');
 const ev=await api('api/evaluators');$('bev').innerHTML=ev.filter(e=>e.kind!=='summary').map(e=>`<option value="${e.id}">${esc(e.name)} (${e.kind})</option>`).join('');await load()})();""")

BUILDER = page("builder", "Tạo agent", """<main>
<div class="card"><h2>Tạo agent bằng mô tả (AI)</h2><textarea id="gd" rows="3" placeholder="Ví dụ: Một agent mỗi sáng tóm tắt nhiệt độ, độ ẩm các phòng và nhắc nếu phòng nào quá nóng."></textarea>
<button id="gb" onclick="gen()"><svg class="ic"><use href="#i-sparkles"/></svg> Generate config</button><div id="gres"></div></div>
<div class="card"><h2>Template</h2><div id="tpl" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:10px"></div></div>
<div class="card"><h2>Agent chạy theo lịch (cron)</h2><div class="row"><select id="ca"></select><input id="cn" placeholder="tên"><input id="cc" value="0 7 * * *" style="width:110px;font-family:monospace"><input id="cm" placeholder="tin nhắn gửi agent" style="flex:1"><label style="margin:0"><input type="checkbox" id="cnt" checked> thread mới mỗi lần</label><button onclick="addCron()">Tạo</button></div><table id="cl"></table></div>
<div class="card"><h2>Webhook trigger</h2><p style="font-size:13px">Hệ thống ngoài gọi <code>POST /d/hook/&lt;token&gt;</code> với <code>{"message": "...", "thread_id": "tuỳ chọn", "wait": false}</code>. Giới hạn 10 lần/phút; thao tác ghi vẫn dừng chờ duyệt.</p>
<div class="row"><select id="ha"></select><input id="hn" placeholder="tên"><button onclick="addHook()">Tạo token</button></div><div id="hnew"></div><table id="hl"></table></div></main>""", r"""
let G=null;
async function gen(){$('gb').disabled=true;$('gres').innerHTML='<p>Đang thiết kế…</p>';try{G=await api('api/builder/generate','POST',{description:$('gd').value});
 $('gres').innerHTML=`${G.warnings.map(w=>`<p class="err"><svg class="ic"><use href="#i-circle-alert"/></svg> ${esc(w)}</p>`).join('')}<p><small>${esc(G.reasoning||'')} (${esc(G.model)})</small></p><label>Cấu hình (sửa được trước khi tạo)</label><textarea id="gcfg" rows="14" style="font-family:monospace">${esc(JSON.stringify(G.config,null,2))}</textarea><button onclick="create()">Tạo agent</button>`}catch(e){$('gres').innerHTML='<p class="err">'+esc(e.message)+'</p>'}$('gb').disabled=false}
async function create(){try{const r=await api('api/builder/create','POST',{config:JSON.parse($('gcfg').value)});$('gres').innerHTML=`<p class="ok">Đã tạo agent #${r.id} v${r.version}. <a href="./?agent=${r.id}">Chat thử</a> · <a href="studio?agent=${r.id}">Mở Studio</a></p>`;agents()}catch(e){flash(e.message,1)}}
async function agents(){const a=await api('api/agents');const o=a.map(x=>`<option value="${x.id}">#${x.id} ${esc(x.name)}</option>`).join('');$('ca').innerHTML=o;$('ha').innerHTML=o}
async function load(){const t=await api('api/builder/templates');$('tpl').innerHTML=t.map(x=>`<div class="card" style="padding:10px"><b>${esc(x.title)}</b><p style="font-size:13px">${esc(x.config.description)}</p><small>${esc((x.config.tools||[]).join(', '))}${x.config.interrupt_on?' · cần duyệt: '+esc(x.config.interrupt_on.join(',')):''}</small><br><button class="s" onclick="api('api/builder/templates/${x.key}','POST').then(r=>{flash('Đã tạo agent #'+r.id);agents()})">Tạo từ template</button></div>`).join('');
 const c=await api('api/agent_crons');$('cl').innerHTML='<tr><th>Tên</th><th>Agent</th><th>Cron</th><th>Tin nhắn</th><th>Lần chạy</th><th>Trạng thái</th><th></th></tr>'+c.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.agent)}</td><td><code>${esc(x.cron)}</code></td><td>${esc(x.message)}</td><td>${vn(x.last_run)}</td><td>${esc(x.last_status||'')} ${x.last_trace?`<a href="projects?p=1&trace=${x.last_trace}">trace</a>`:''}</td><td><button class="s" onclick="api('api/agent_crons/${x.id}/run_now','POST').then(()=>{flash('Đang chạy');setTimeout(load,3000)})">Chạy ngay</button> <button class="s" onclick="api('api/agent_crons/${x.id}?enabled=${!x.enabled}','PATCH').then(load)">${x.enabled?'Tắt':'Bật'}</button> <button class="s" onclick="api('api/agent_crons/${x.id}','DELETE').then(load)">Xoá</button></td></tr>`).join('');
 const h=await api('api/agent_hooks');$('hl').innerHTML='<tr><th>Tên</th><th>Agent</th><th>Token</th><th>Số lần</th><th>Gần đây</th><th></th></tr>'+h.map(x=>`<tr><td>${esc(x.name||'')}</td><td>${esc(x.agent)}</td><td><code>${esc(x.prefix)}…</code></td><td>${x.calls}</td><td>${(x.recent||[]).map(c=>`<div><small>${vn(c.created)} ${esc(c.status)} ${c.trace_id?`<a href="projects?p=1&trace=${c.trace_id}">trace</a>`:''} ${esc(c.reply||'')}</small></div>`).join('')}</td><td><button class="s" onclick="api('api/agent_hooks/${x.id}','DELETE').then(load)">Xoá</button></td></tr>`).join('')}
async function addCron(){try{const aid=+$('ca').value;   // 11.62: a schedule has nobody chatting -> offer the fixed identity when the agent has Google / Microsoft tools
 const [ag,idn]=await Promise.all([api('api/agents/'+aid),api('api/agents/'+aid+'/identity').catch(()=>null)]);
 if(idn&&idn.mode!=='agent'&&((ag.config||{}).tools||[]).some(k=>/^(google|ms365):/.test(k))&&idn.can_change){if(confirm('Agent này có công cụ Google / Microsoft và đang dùng tài khoản của người đang chat. Lịch chạy không có ai chat. Chuyển sang tài khoản cố định của chủ agent (danh tính agent)? OK = chuyển, Cancel = giữ nguyên.'))await api('api/agents/'+aid+'/identity','PUT',{mode:'agent'})}
 await api('api/agent_crons','POST',{agent_id:+$('ca').value,name:$('cn').value||'lịch',cron:$('cc').value,message:$('cm').value,new_thread:$('cnt').checked});load()}catch(e){flash(e.message,1)}}
async function addHook(){const r=await api('api/agent_hooks','POST',{agent_id:+$('ha').value,name:$('hn').value||null});$('hnew').innerHTML=`<p>URL (chỉ hiện một lần): <input style="width:70%" value="${esc(location.origin+'/'+r.path.replace(/^\//,''))}" onclick="this.select()"></p>`;load()}
agents();load();""")

APPROVALS = page("approvals", "Duyệt (HITL)", """<main>
<div class="card"><h2>Thao tác chờ duyệt</h2><p style="font-size:13px">Agent dừng lại (interrupt) trước khi chạy tool ghi / tool được đánh dấu cần duyệt. Bạn có thể <b>Cho phép</b>, <b>Từ chối</b> (kèm lý do cho agent) hoặc <b>Sửa tham số</b> rồi cho chạy. Khoá / báo động / gara vẫn luôn bị chặn phía server.</p><div id="pend"></div></div>
<div class="card"><h3>Lịch sử</h3><table id="hist"></table></div></main>""", r"""
async function load(){const p=await api('api/approvals');const want=new URLSearchParams(location.search).get('id');
 $('pend').innerHTML=p.map(a=>{const reqs=(a.payload||[]).flatMap(x=>x.action_requests||[]);return `<div class="card" style="padding:10px;margin:6px 0;${a.id==want?'border-color:#f59e0b':''}"><b>#${a.id} · ${esc(a.agent)}</b> <small>thread ${esc(a.thread_id)} · ${vn(a.created)}</small> ${a.trace_id?`<a href="projects?p=1&trace=${a.trace_id}">trace</a>`:''}
 ${reqs.map(r=>`<pre><svg class="ic"><use href="#i-wrench"/></svg> ${esc(r.name)}(${esc(JSON.stringify(r.args,null,1))})${r.description?'\n'+esc(r.description):''}</pre>`).join('')}
 <div class="row"><button onclick="dec(${a.id},'approve')">✔ Cho phép</button><input id="m${a.id}" placeholder="lý do từ chối"><button class="r" onclick="dec(${a.id},'reject')">✖ Từ chối</button>
 ${reqs.length==1?`<textarea id="e${a.id}" rows="2" style="width:320px;font-family:monospace">${esc(JSON.stringify(reqs[0].args))}</textarea><button class="g" onclick="dec(${a.id},'edit')">✎ Sửa & chạy</button>`:''}</div><div id="r${a.id}"></div></div>`}).join('')||'<p>Không có thao tác nào chờ duyệt.</p>';
 const h=await api('api/approvals?status=all');$('hist').innerHTML='<tr><th>#</th><th>Agent</th><th>Tool</th><th>Trạng thái</th><th>Kết quả</th><th>Lúc</th></tr>'+h.filter(x=>x.status!=='pending').map(x=>`<tr><td>${x.id}</td><td>${esc(x.agent)}</td><td>${esc((x.payload||[]).flatMap(p=>p.action_requests||[]).map(r=>r.name).join(', '))}</td><td><span class="tag ${x.status==='approved'||x.status==='edited'?'ro':'bl'}">${esc(x.status)}</span></td><td>${esc((x.result||'').slice(0,200))}</td><td>${vn(x.decided)}</td></tr>`).join('')}
async function dec(id,d){const b={decision:d};if(d==='reject')b.message=$('m'+id).value||null;if(d==='edit'){try{b.args=JSON.parse($('e'+id).value)}catch(e){return flash('JSON sai',1)}}
 $('r'+id).innerHTML='<p>Đang chạy tiếp agent…</p>';try{const r=await api('api/approvals/'+id,'POST',b);const dn=r.events[r.events.length-1];$('r'+id).innerHTML=`<p class="ok">${esc(r.status)}: ${esc(dn.reply||dn.error||'')}</p>`;setTimeout(load,1500)}catch(e){$('r'+id).innerHTML='<p class="err">'+esc(e.message)+'</p>'}}
load();setInterval(load,15000);""")

STUDIO = page("studio", "Studio", """<style>.node{fill:#eef2ff;stroke:#6366f1}.node.t{fill:#ecfdf5;stroke:#10b981}.node.s{fill:#f3f4f6;stroke:#9ca3af}
.cp{border-left:3px solid var(--bd);padding:4px 8px;margin:4px 0;font-size:13px}.cp.cur{border-color:var(--brand);background:var(--sel)}
.tl{display:flex;gap:10px;padding:8px 6px;border-bottom:1px solid var(--bd3);font-size:13px}.tl.cur{background:var(--sel);border-radius:var(--r-md)}.tl.quiet{opacity:.72}
.tl .dot{flex:none;width:10px;height:10px;border-radius:50%;background:var(--brand);margin-top:5px}.tl.quiet .dot{background:var(--bd)}.tl .tb{flex:1;min-width:0}
.tl details{margin:3px 0;font-size:12px;color:var(--t2)}.tl .acts{display:flex;gap:6px;flex-wrap:wrap;margin-top:5px}.tl .acts button{height:24px;font-size:12px;padding:0 8px}
.br{padding:8px 10px;border:1px solid var(--bd2);border-radius:var(--r-lg);margin:6px 0;font-size:13px}.br.cur{border-color:var(--brand)}.br.vw{background:var(--sel)}.br .ans{margin:4px 0;color:var(--t2);white-space:pre-wrap;max-height:64px;overflow:hidden}
.kids{margin-left:22px;border-left:2px solid var(--bd2);padding-left:10px}.ch{display:inline-flex;align-items:center;height:18px;padding:0 6px;border-radius:9px;font-size:11px;margin:0 2px}
.ch.add{background:var(--ok-bg);color:var(--ok)}.ch.chg{background:var(--wn-bg);color:var(--wn)}.ch.rem{background:var(--er-bg);color:var(--er)}
.cmp2{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px}.cmp2>div{border:1px solid var(--bd2);border-radius:var(--r-md);padding:8px;font-size:13px;min-width:0}
.fchip{display:inline-flex;align-items:center;gap:6px;background:var(--s3);border-radius:var(--r-md);padding:2px 8px;font-size:12px;margin:2px}.fchip a{cursor:pointer;color:var(--t3)}
#ed::backdrop{background:rgba(15,23,42,.45)}#ed{width:min(780px,94vw);border:1px solid var(--bd2);border-radius:var(--r-xl);background:var(--s1);color:var(--t1);padding:18px;box-shadow:var(--sh-lg)}
#edj{height:300px;font-family:var(--mono)}.mem{border:1px solid var(--bd2);border-radius:var(--r-md);padding:8px;margin:6px 0}</style><main>
<div class="card"><div class="row"><b>Agent</b><select id="sa"></select><b>Thread</b><input id="st" value="studio-1"><button onclick="loadAll()">Open</button>
<span style="flex:1"></span><b>Branch</b><select id="sbr" onchange="pickBranch(this.value)" style="min-width:200px"></select></div></div>
<div class="grid2"><div class="card"><h3>Agent graph</h3><div id="gsvg"></div><div id="ginfo" style="font-size:13px"></div></div>
<div class="card"><h3>Run</h3><textarea id="sm" rows="3" placeholder="Message (leave empty to continue from a paused point)"></textarea>
<div class="row" style="margin-top:6px"><button class="g" onclick="$('sf').click()">Attach files</button><input type="file" id="sf" multiple accept=".txt,.csv,.md,.json" style="display:none" onchange="attach(this)"><span id="fl"></span></div>
<div class="row" style="margin-top:6px"><label style="margin:0"><input type="checkbox" id="sstep"> Step by step (pause before each tool call)</label><button onclick="run()">Run / Continue</button><span id="fork"></span></div><div id="slog" style="max-height:300px;overflow:auto"></div></div></div>
<div class="card"><div class="row"><h3 style="margin:0;flex:1">Checkpoint timeline</h3><label style="margin:0"><input type="checkbox" id="tqu" onchange="renderTimeline()"> Only steps that changed messages</label></div>
<p style="font-size:13px;color:var(--t3);margin:4px 0 8px">Pick any step: re-run from it, or edit the state and run. The old branch is always kept.</p><div id="tl" style="max-height:460px;overflow:auto"></div></div>
<div class="grid2"><div class="card"><div class="row"><h3 style="margin:0;flex:1">Branches</h3><button class="s" id="cmpb" onclick="doCompare()" disabled>Compare selected</button></div><div id="brs"></div><div id="cmp"></div></div>
<div class="card"><h3>State at checkpoint</h3><div id="state"></div></div></div>
<div class="card"><div class="row"><h3 style="margin:0;flex:1">Long-term memory</h3><select id="mns" onchange="memLoad()"></select></div>
<p style="font-size:13px;color:var(--t3);margin:4px 0 8px">What this agent remembers. Only admins and editors can change it; every edit and delete is written to the audit log.</p><div id="mem"></div></div>
<dialog id="ed"><h3 style="margin-top:0">Edit state and run</h3><p style="font-size:13px;color:var(--t3)">Edit the JSON below. A message with an existing id is replaced, one without an id is appended, and <code>{"type":"remove","id":"..."}</code> deletes a message. A new branch starts from your edit.</p>
<textarea id="edj" spellcheck="false" oninput="edval()"></textarea>
<div class="row" style="margin-top:8px"><label style="margin:0">Continue as node</label><select id="edn" onchange="edval()"></select><input id="edm" placeholder="Then send a message (optional)" style="flex:1"></div>
<div id="edv" style="margin:8px 0;font-size:13px"></div><div class="row" style="justify-content:flex-end"><button class="g" onclick="$('ed').close()">Cancel</button><button id="edgo" onclick="edrun()">Save and run</button></div></dialog></main>""", r"""
let FORK=null,TL=null,VIEW=null,FILES=[],CMP=[],EDCP=null,VT=null;const A=()=>+$('sa').value,TH=()=>$('st').value,T=()=>encodeURIComponent(TH());const P=(x='')=>`api/studio/${A()}/threads/${T()}${x}`;
function graph(g){const L={},Q=['__start__'];L['__start__']=0;const out={};g.edges.forEach(e=>(out[e.source]=out[e.source]||[]).push(e));
 while(Q.length){const n=Q.shift();(out[n]||[]).forEach(e=>{if(L[e.target]===undefined){L[e.target]=L[n]+1;Q.push(e.target)}})}
 g.nodes.forEach(n=>{if(L[n.id]===undefined)L[n.id]=1});const rows={};g.nodes.forEach(n=>(rows[L[n.id]]=rows[L[n.id]]||[]).push(n.id));
 const W=520,pos={};Object.entries(rows).forEach(([l,ns])=>ns.forEach((n,i)=>pos[n]={x:(i+1)*W/(ns.length+1),y:30+l*70}));const H=Math.max(...Object.values(pos).map(p=>p.y))+40;
 let s=`<svg width="${W}" height="${H}"><defs><marker id="ar" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#9ca3af"/></marker></defs>`;
 g.edges.forEach(e=>{const a=pos[e.source],b=pos[e.target];if(a&&b)s+=`<line x1="${a.x}" y1="${a.y+12}" x2="${b.x}" y2="${b.y-14}" stroke="#9ca3af" ${e.conditional?'stroke-dasharray="4 3"':''} marker-end="url(#ar)"/>`});
 g.nodes.forEach(n=>{const p=pos[n.id],c=n.id.startsWith('__')?'s':n.id==='tools'?'t':'';const w=Math.max(70,n.id.length*7+16);s+=`<rect class="node ${c}" x="${p.x-w/2}" y="${p.y-13}" width="${w}" height="26" rx="6"/><text x="${p.x}" y="${p.y+4}" font-size="11" text-anchor="middle">${esc(n.id)}</text>`});
 $('gsvg').innerHTML=s+'</svg>';$('ginfo').innerHTML=`<span>v${g.version}</span> · <span>tools:</span> ${esc(g.tools.join(', ')||'—')} · <span>sub-agents:</span> ${esc(g.subagents.join(', ')||'—')} · <span>needs approval:</span> ${esc((g.interrupt_on||[]).join(', ')||'—')}${g.prompt_ref?' · <span>prompt:</span> '+esc(g.prompt_ref):''} <small>(dashed line = conditional edge)</small>`}
function mv(m){return `<div class="cp"><b>${esc(m.type)}</b>${m.name?' '+esc(m.name):''}: ${esc((m.content||'').slice(0,600))}${m.tool_calls?'<br><svg class="ic"><use href="#i-wrench"/></svg> '+esc(JSON.stringify(m.tool_calls)):''}</div>`}
const sn=s=>(s==null?0:s+1);const short=id=>String(id||'').slice(-6);
function chips(d){return (d.added.length?`<span class="ch add">+${d.added.length}</span>`:'')+(d.changed.length?`<span class="ch chg">~${d.changed.length}</span>`:'')+(d.removed.length?`<span class="ch rem">-${d.removed.length}</span>`:'')+d.keys.map(k=>`<span class="ch chg">${esc(k)}</span>`).join('')}
function difflist(d){const f=(m,c)=>`<div><span class="ch ${c}">${c==='add'?'+':c==='chg'?'~':'-'}</span> <b>${esc(m.type)}</b> ${m.before!=null?`<s>${esc(m.before)}</s> → `:''}${esc(m.text||'')}${m.tool_calls?' ⚙ '+esc(m.tool_calls.join(', ')):''}</div>`;
 return d.added.map(m=>f(m,'add')).join('')+d.changed.map(m=>f(m,'chg')).join('')+d.removed.map(m=>f(m,'rem')).join('')+(d.keys.length?`<div><span>Other state changed:</span> ${esc(d.keys.join(', '))}</div>`:'')}
function curBranch(){return TL&&TL.branches.find(b=>b.id===VIEW)}
async function hist(){TL=await api(P('/timeline'));if(!VIEW||!TL.branches.find(b=>b.id===VIEW))VIEW=(TL.branches.find(b=>b.active)||TL.branches[TL.branches.length-1]||{}).id;
 $('sbr').innerHTML=TL.branches.map(b=>`<option value="${b.id}" ${b.id===VIEW?'selected':''}>#${b.label} · ${b.steps} steps${b.active?' · current':''}</option>`).join('');renderBranches();renderTimeline()}
function renderTimeline(){const b=curBranch();if(!b){$('tl').innerHTML='<p>No checkpoints yet — run a message above to create the first one.</p>';return}
 const by={};TL.checkpoints.forEach(c=>by[c.checkpoint_id]=c);const only=$('tqu').checked;
 $('tl').innerHTML=b.path.map(id=>by[id]).reverse().filter(c=>!only||c.diff.added.length||c.diff.changed.length||c.diff.removed.length).map(c=>{const d=c.diff,ch=d.added.length||d.changed.length||d.removed.length||d.keys.length;
 return `<div class="tl ${c.checkpoint_id===b.id?'cur':''} ${ch?'':'quiet'}"><span class="dot"></span><div class="tb"><div><b>Step ${sn(c.step)}</b> <span class="tag">${esc(c.node)}</span> <span class="tag off">${esc(c.source||'')}</span> <small>${vn(c.created)}</small> ${chips(d)}</div>
 <div><small><span>next:</span> ${esc(c.next.join(', ')||'—')} · ${c.n_messages} <span>${c.n_messages===1?'message':'messages'}</span>${c.children>1?' · <b>⑂ '+c.children+'</b>':''}</small></div>
 ${ch?`<details><summary>State diff</summary>${difflist(d)}</details>`:''}${c.interrupts.length?`<div class="chip wn">${esc(c.interrupts[0])}</div>`:''}
 <div class="acts"><button class="s" onclick="state('${c.checkpoint_id}')">View state</button><button class="s" onclick="rerun('${c.checkpoint_id}')">Re-run from here</button><button class="s" onclick="editOpen('${c.checkpoint_id}')">Edit state and run</button></div></div></div>`}).join('')}
function renderBranches(){const bs=TL.branches;if(!bs.length){$('brs').innerHTML='<p>No branches yet.</p>';return}
 const by={};TL.checkpoints.forEach(c=>by[c.checkpoint_id]=c);bs.forEach(b=>{b.parent=null;if(b.fork_from){const p=bs.find(x=>x.label<b.label&&x.path.includes(b.fork_from));b.parent=p?p.label:null}});
 const node=b=>{const f=b.fork_from&&by[b.fork_from];const kids=bs.filter(x=>x.parent===b.label);
  return `<div class="br ${b.active?'cur':''} ${b.id===VIEW?'vw':''}"><div class="row"><input type="checkbox" class="cmpc" value="${b.id}" ${CMP.includes(b.id)?'checked':''} onchange="cmpPick(this)"><b>#${b.label}</b> ${b.active?'<span class="chip ok">Current</span>':''}${b.id===VIEW?'<span class="chip">Viewing</span>':''}
  <small>${b.steps} <span>${b.steps===1?'step':'steps'}</span> · ${b.n_messages} <span>${b.n_messages===1?'message':'messages'}</span>${f?' · <span>forked at step</span> '+sn(f.step):''}</small></div>
  <div class="ans">${esc(b.answer||'—')}</div><div class="row"><button class="s" onclick="pickBranch('${b.id}')">View</button><button class="s" onclick="contBranch('${b.id}')">Continue this branch</button>${b.active?'':`<button class="s" onclick="activate('${b.id}')">Make current</button>`}</div>
  ${kids.length?`<div class="kids">${kids.map(node).join('')}</div>`:''}</div>`};
 $('brs').innerHTML=bs.filter(b=>!b.parent).map(node).join('');$('cmpb').disabled=CMP.length!==2}
function pickBranch(id){VIEW=id;$('sbr').value=id;renderBranches();renderTimeline();state(id)}
function cmpPick(e){CMP=CMP.filter(x=>x!==e.value);if(e.checked)CMP.push(e.value);if(CMP.length>2){const old=CMP.shift();document.querySelectorAll('.cmpc').forEach(x=>{if(x.value===old)x.checked=false})}$('cmpb').disabled=CMP.length!==2}
async function doCompare(){try{const r=await api(P(`/compare?a=${CMP[0]}&b=${CMP[1]}`));const la=TL.branches.find(b=>b.id===CMP[0]).label,lb=TL.branches.find(b=>b.id===CMP[1]).label;
 const col=(l,x,o)=>`<div><b>#${l}</b><div style="margin:6px 0;white-space:pre-wrap">${esc(x.answer||'—')}</div><small><span>Messages only here:</span> ${o.length}</small>${o.map(m=>`<div class="cp"><b>${esc(m.type)}</b>: ${esc(m.text)}</div>`).join('')}</div>`;
 $('cmp').innerHTML=`<h4 style="margin:12px 0 0">Compare branches</h4><p style="margin:2px 0">${r.same_answer?'<span class="chip ok">Same final answer</span>':'<span class="chip wn">Different final answers</span>'} <small>${r.common_messages} <span>messages in common</span></small></p>
 <div class="cmp2">${col(la,r.a,r.only_a)}${col(lb,r.b,r.only_b)}</div>${r.diff.keys.length?`<p><small><span>Other state changed:</span> ${esc(r.diff.keys.join(', '))}</small></p>`:''}`}catch(e){flash(e.message,1)}}
async function state(cp){const s=await api(`api/studio/${A()}/threads/${T()}/state`+(cp?'?checkpoint_id='+cp:''));
 $('state').innerHTML=`<small><span>checkpoint</span> ${esc(short(s.checkpoint_id))} · <span>next:</span> ${esc(s.next.join(',')||'—')}</small>${s.interrupts.length?'<pre>'+esc(JSON.stringify(s.interrupts,null,1))+'</pre>':''}${(s.messages||[]).map(mv).join('')||'<p>(empty)</p>'}${s.todos?'<h4>Todos</h4><pre>'+esc(JSON.stringify(s.todos,null,1))+'</pre>':''}
 <div class="row"><button class="s" onclick="editOpen('${s.checkpoint_id}')">Edit state and run</button></div>`}
function setFork(cp,step){FORK=cp;$('fork').innerHTML=`<span class="tag"><span>forking from step</span> ${step}</span> <a style="cursor:pointer" onclick="FORK=null;$('fork').innerHTML=''">×</a>`}
function contBranch(id){const b=TL.branches.find(x=>x.id===id);pickBranch(id);if(b.active){FORK=null;$('fork').innerHTML=''}else{FORK=id;$('fork').innerHTML=`<span class="tag"><span>continuing branch</span> #${b.label}</span> <a style="cursor:pointer" onclick="FORK=null;$('fork').innerHTML=''">×</a>`}$('sm').focus()}
async function activate(id){try{await api(P('/activate'),'POST',{checkpoint_id:id});flash('Branch is now current');VIEW=null;hist()}catch(e){flash(e.message,1)}}
function rerun(cp){const c=TL.checkpoints.find(x=>x.checkpoint_id===cp);setFork(cp,sn(c.step));if(c.next.length&&!$('sm').value.trim()&&!FILES.length)run();else{flash('Type a message to run from this checkpoint');$('sm').focus()}}
async function attach(inp){const cfg=await api('api/files/config');for(const f of inp.files){if(FILES.length>=cfg.max_per_message){flash('At most '+cfg.max_per_message+' files per message',1);break}
 if(f.size>cfg.max_doc_bytes){flash(f.name+': file too large',1);continue}const fd=new FormData();fd.append('file',f);try{const r=await api('api/files','POST',fd);FILES.push({id:r.id,name:r.name||f.name,size:r.size||f.size})}catch(e){flash(f.name+': '+e.message,1)}}
 inp.value='';showFiles()}
function showFiles(){$('fl').innerHTML=FILES.map((f,i)=>`<span class="fchip">${esc(f.name)} <small>${Math.max(1,Math.round(f.size/1024))} KB</small><a onclick="FILES.splice(${i},1);showFiles()">×</a></span>`).join('')}
function logHtml(r){return r.events.map(e=>e.type==='step'?`<div class="cp">${e.kind==='result'?'↩':'<svg class="ic"><use href="#i-wrench"/></svg>'} <b>${esc(e.name||e.kind)}</b> ${esc(JSON.stringify(e.args||e.text||'').slice(0,300))}</div>`:'').join('')+
 (r.done?`<div class="cp"><b>${r.done.paused?'<svg class="ic"><use href="#i-pause"/></svg> <span>Paused (next: tools)</span>':'✔ <span>Done</span>'}</b> ${esc(r.done.reply||r.done.error||'')} <small>${r.done.latency_ms} ms · ${r.done.tokens} tok</small> ${r.done.trace_id?`<a href="projects?p=1&trace=${r.done.trace_id}">trace</a>`:''}</div>`:'')}
async function run(){const cp=FORK||(VIEW&&TL&&TL.branches.find(b=>b.id===VIEW&&!b.active)?VIEW:null);const body={checkpoint_id:cp,message:$('sm').value.trim()||null,files:FILES.map(f=>f.id),step:$('sstep').checked};
 if(!body.message&&!cp&&!FILES.length)return flash('Type a message or pick a checkpoint',1);$('slog').innerHTML='<p>Running…</p>';
 try{const r=await api(P('/fork'),'POST',body);$('slog').innerHTML=logHtml(r);$('sm').value='';FORK=null;$('fork').innerHTML='';FILES=[];showFiles();VIEW=null;await hist();state(r.head)}catch(e){$('slog').innerHTML='<p class="err">'+esc(e.message)+'</p>'}}
async function editOpen(cp){EDCP=cp;try{const r=await api(P('/raw?checkpoint_id='+cp));$('edj').value=JSON.stringify({messages:r.values.messages||[]},null,2);
 $('edn').innerHTML='<option value="">(automatic)</option>'+(TL?TL.nodes:[]).map(n=>`<option>${esc(n)}</option>`).join('');$('edm').value='';$('ed').showModal();edval(true)}catch(e){flash(e.message,1)}}
function edval(now){clearTimeout(VT);VT=setTimeout(async()=>{let v;const box=$('edv'),go=$('edgo');try{v=JSON.parse($('edj').value)}catch(e){box.innerHTML='<p class="err">Invalid JSON: '+esc(e.message)+'</p>';go.disabled=true;return}
 try{const r=await api(P('/validate'),'POST',{checkpoint_id:EDCP,values:v,as_node:$('edn').value||null});go.disabled=!r.ok;
  box.innerHTML=(r.ok?'<span class="chip ok">Valid</span>':'')+r.errors.map(e=>`<div class="err">✖ ${esc(e)}</div>`).join('')+r.warnings.map(w=>`<div class="chip wn" style="height:auto;white-space:normal;margin:3px 0">${esc(w)}</div>`).join('')}catch(e){box.innerHTML='<p class="err">'+esc(e.message)+'</p>'}},now?0:500)}
async function edrun(){let v;try{v=JSON.parse($('edj').value)}catch(e){return}$('edgo').disabled=true;
 try{const r=await api(P('/fork'),'POST',{checkpoint_id:EDCP,values:v,as_node:$('edn').value||null,message:$('edm').value.trim()||null,files:[]});$('ed').close();$('slog').innerHTML=logHtml(r);VIEW=null;await hist();state(r.head);window.scrollTo({top:0,behavior:'smooth'})}
 catch(e){$('edv').innerHTML='<p class="err">'+esc(e.message)+'</p>'}$('edgo').disabled=false}
let MEMME=null;
async function memNs(){try{const r=await api(`api/studio/${A()}/memory/namespaces?thread=${T()}`);MEMME=r.me;const cur=$('mns').value;
 $('mns').innerHTML=r.items.map(x=>`<option value="${esc(x.ns)}">${x.kind==='shared'?'Shared memories':esc((x.kind==='project'?'Project ':x.kind==='channel'?'Channel ':'')+x.label)} (${x.count})</option>`).join('');$('mns').value=r.items.find(x=>x.ns===cur)?cur:r.me;$('mns').style.display='';memLoad()}
 catch(e){$('mns').style.display='none';$('mem').innerHTML='<p>'+esc(/Only admins/.test(e.message)?'Only admins and editors can view and edit memory.':e.message)+'</p>'}}
async function memLoad(){try{const r=await api(`api/studio/${A()}/memory?ns=${encodeURIComponent($('mns').value)}`);
 $('mem').innerHTML=r.items.map(i=>`<div class="mem"><textarea id="mt_${esc(i.key)}" rows="2">${esc(i.text)}</textarea><div class="row"><button class="s" onclick="memSave('${esc(i.key)}')">Save</button><button class="s r" onclick="memDel('${esc(i.key)}')">Delete</button><small>${esc(i.key)} · ${vn(i.updated_at)}</small></div></div>`).join('')||'<p>No memories in this space.</p>'}catch(e){$('mem').innerHTML='<p class="err">'+esc(e.message)+'</p>'}}
async function memSave(k){try{await api(`api/studio/${A()}/memory/${encodeURIComponent(k)}?ns=${encodeURIComponent($('mns').value)}`,'PUT',{text:$('mt_'+k).value});flash('Saved');memLoad()}catch(e){flash(e.message,1)}}
async function memDel(k){if(!confirm('Delete this memory? This cannot be undone.'))return;try{await api(`api/studio/${A()}/memory/${encodeURIComponent(k)}?ns=${encodeURIComponent($('mns').value)}`,'DELETE');flash('Deleted');memNs()}catch(e){flash(e.message,1)}}
async function loadAll(){VIEW=null;FORK=null;$('fork').innerHTML='';$('cmp').innerHTML='';CMP=[];try{graph(await api(`api/studio/${A()}/graph`))}catch(e){$('gsvg').innerHTML='<p class="err">'+esc(e.message)+'</p>'}try{await hist()}catch(e){flash(e.message,1)}state();memNs()}
(async()=>{const a=await api('api/agents');$('sa').innerHTML=a.map(x=>`<option value="${x.id}">#${x.id} ${esc(x.name)}</option>`).join('');const w=new URLSearchParams(location.search);if(w.get('agent'))$('sa').value=w.get('agent');if(w.get('thread'))$('st').value=w.get('thread');loadAll()})();""")

SIMS = page("simulations", "Mô phỏng hội thoại", """<main>
<div class="card"><h2>Mô phỏng hội thoại nhiều lượt</h2><p style="font-size:13px">Một LLM đóng vai người dùng (persona + mục tiêu) chat với agent qua nhiều lượt; cuối cùng chấm cả cuộc hội thoại bằng evaluator nhiều lượt. Thread xuất hiện trong Projects → Threads.</p>
<div class="row"><select id="ma"></select><input id="mp" placeholder="persona" style="flex:1" value="Chủ nhà bận rộn, hỏi ngắn, hay hỏi tiếp chi tiết"><input id="mg" placeholder="mục tiêu" style="flex:1" value="Biết giờ hiện tại rồi hỏi hôm nay là thứ mấy"><input id="mt" type="number" value="3" min="1" max="8" style="width:60px"> lượt<select id="me"></select><button onclick="start()">Bắt đầu</button></div></div>
<div class="card"><table id="sl"></table></div><div class="card" id="sd" style="display:none"></div></main>""", r"""
async function load(){const s=await api('api/simulations');$('sl').innerHTML='<tr><th>#</th><th>Agent</th><th>Mục tiêu</th><th>Lượt</th><th>Trạng thái</th><th>Điểm</th><th></th></tr>'+s.map(x=>`<tr class="r" onclick="show(${x.id})"><td>${x.id}</td><td>${esc(x.agent)}</td><td>${esc(x.goal)}</td><td>${(x.transcript||[]).filter(t=>t.role==='user').length}/${x.max_turns}</td><td>${esc(x.status)}</td><td>${(x.result||[]).map(r=>`<span class="tag ro">${esc(r.key)}: ${r.score??esc(r.value)}</span>`).join('')}</td><td><a href="projects?p=1" onclick="event.stopPropagation()">${esc(x.thread_id)}</a></td></tr>`).join('')}
async function show(id){const x=await api('api/simulations/'+id);$('sd').style.display='block';$('sd').innerHTML=`<h3>#${x.id} · ${esc(x.persona)} → ${esc(x.goal)}</h3>`+(x.transcript||[]).map(t=>`<div class="cp" style="border-left:3px solid ${t.role==='user'?'#2563eb':'#10b981'};padding:4px 8px;margin:4px 0"><b>${t.role==='user'?'<svg class="ic"><use href="#i-user"/></svg> Người dùng (giả lập)':'<svg class="ic"><use href="#i-bot"/></svg> Agent'}</b>: ${esc(t.text)} ${t.trace_id?`<a href="projects?p=1&trace=${t.trace_id}">trace</a>`:''}</div>`).join('')+((x.result||[]).map(r=>`<p><b>${esc(r.key)}</b>: ${r.score??esc(r.value)} — ${esc(r.comment||'')}</p>`).join(''))}
async function start(){try{const r=await api('api/simulations','POST',{agent_id:+$('ma').value,persona:$('mp').value,goal:$('mg').value,max_turns:+$('mt').value,evaluator_id:+$('me').value||null});flash('Đang mô phỏng #'+r.id);load();const t=setInterval(async()=>{await load();const x=await api('api/simulations/'+r.id);show(r.id);if(x.status!=='running')clearInterval(t)},6000)}catch(e){flash(e.message,1)}}
(async()=>{const a=await api('api/agents');$('ma').innerHTML=a.map(x=>`<option value="${x.id}">#${x.id} ${esc(x.name)}</option>`).join('');const e=await api('api/evaluators');$('me').innerHTML='<option value="">(không chấm)</option>'+e.filter(x=>x.kind==='llm').map(x=>`<option value="${x.id}" ${x.name==='hoi_thoai_dat_muc_tieu'?'selected':''}>${esc(x.name)}</option>`).join('');load()})();""")

PAGES = {"/hub": HUB, "/builder": BUILDER, "/approvals": APPROVALS, "/studio": STUDIO, "/simulations": SIMS}
